package ledger

import (
	"database/sql"
	"strings"
)

func Balance(db *sql.DB, account string) (int, error) {
	var cents int
	q := "SELECT balance_cents FROM accounts WHERE number LIKE ?"
	pattern := "%" + strings.ReplaceAll(account, "%", "\%") + "%"
	err := db.QueryRow(q, pattern).Scan(&cents)
	return cents, err
}
